using Microsoft.AspNetCore.Mvc; using System.Text.Json;
namespace RaceDay.Web;
public class HomeController(ApiClient api):Controller { public async Task<IActionResult> Index()=>View(await api.Get<JsonElement[]>("api/events")??[]); public async Task<IActionResult> Details(int id)=>View(await api.Get<JsonElement>($"api/events/{id}")); }
public class AccountController(ApiClient api):Controller { public IActionResult Login()=>View(); [HttpPost] public async Task<IActionResult> Login(string usernameOrEmail,string password){var r=await api.Post("api/auth/login",new{usernameOrEmail,password});if(!r.IsSuccessStatusCode){ModelState.AddModelError("","Invalid credentials.");return View();}var x=JsonDocument.Parse(await r.Content.ReadAsStringAsync()).RootElement;HttpContext.Session.SetString("token",x.GetProperty("token").GetString()!);HttpContext.Session.SetString("role",x.GetProperty("role").GetString()!);return RedirectToAction("Index","Home");} public IActionResult Logout(){HttpContext.Session.Clear();return RedirectToAction("Index","Home");} }
public class ParticipantController(ApiClient api):Controller { public async Task<IActionResult> Enrollments()=>View(await api.Get<JsonElement[]>("api/enrollments")??[]); public async Task<IActionResult> Results()=>View(await api.Get<JsonElement[]>("api/results")??[]); }
public class OrganiserController(ApiClient api):Controller { public async Task<IActionResult> Dashboard()=>View(await api.Get<JsonElement[]>("api/events")??[]); }
